def _save_5method_format(all_pairs, n_gens, exp_dir, analysis_dir):
    """Save lead-lag results in the format expected by MMCT module."""
    pairs_out = []
    for p in all_pairs:
        r = p["results"]
        pair_entry = {
            "canary": p["canary"],
            "downstream": p["downstream"],
            "forward": {},
            "reverse": {},
        }
        for method in ["naive_xcorr", "diff_xcorr", "threshold_onset", "ty_granger"]:
            if method in r:
                pair_entry["forward"][method] = r[method]
        if "perm_granger_fwd" in r:
            pair_entry["forward"]["perm_granger"] = r["perm_granger_fwd"]
        if "perm_granger_rev" in r:
            pair_entry["reverse"]["perm_granger"] = r["perm_granger_rev"]
        pairs_out.append(pair_entry)

    output = {
        "n_generations": n_gens,
        "data_dir": exp_dir,
        "methods": ["naive_xcorr", "diff_xcorr", "threshold_onset",
                     "perm_granger", "ty_granger"],
        "pairs": pairs_out,
    }
    path = os.path.join(analysis_dir, "5method_leadlag.json")
    with open(path, "w") as f:
        json.dump(_clean(output), f, indent=2)


def _clean(obj):
    if isinstance(obj, (np.floating, np.float64, np.float32)):
        return float(obj)
    if isinstance(obj, (np.integer,)):
        return int(obj)
    if isinstance(obj, np.bool_):
        return bool(obj)
    if isinstance(obj, dict):
        return {k: _clean(v) for k, v in obj.items()}
    if isinstance(obj, list):
        return [_clean(v) for v in obj]
    if isinstance(obj, np.ndarray):
        return [_clean(v) for v in obj.tolist()]
    return obj


